/** Instantiates the program; `options.facilities` provides the facilities it needs. */
export async function load(options = {}) {
  const program = await L.Program.load(options.module ?? (await programModule()), { wasi: options.wasi });
  program.types("swf_models__types");
  return new SwfModels(program);
}
